-- Additive baseline. Existing tables and identifiers are retained.
begin;
create extension if not exists pgcrypto;
create table if not exists users (id uuid primary key default gen_random_uuid(), email text unique not null, password_hash text, name text not null default '', phone text, address text, is_admin boolean not null default false, email_verified boolean default false, google_id text, created_at timestamptz default now());
create table if not exists categories (id bigint generated by default as identity primary key, name text not null, slug text unique, description text, image_url text, created_at timestamptz default now());
create table if not exists artisans (id bigint generated by default as identity primary key, name text not null, bio text, specialty text, location text, image_url text, active boolean default true, created_at timestamptz default now());
create table if not exists products (id uuid primary key default gen_random_uuid(), title text not null, description text, price numeric(12,2) not null check(price>=0), discount_percent integer default 0 check(discount_percent between 0 and 100), stock integer default 0 check(stock>=0), category_id bigint references categories(id), artisan_id bigint references artisans(id), featured boolean default false, is_flash_sale boolean default false, flash_sale_ends_at timestamptz, allow_preorder boolean default false, is_listed boolean default true, crafting_days integer default 7, images jsonb default '[]', created_at timestamptz default now());
create table if not exists variants (id bigint generated by default as identity primary key, product_id uuid references products(id), name text not null, value text not null, price_modifier numeric(12,2) default 0, stock integer default 0, sku text, created_at timestamptz default now());
create table if not exists coupons (id bigint generated by default as identity primary key, code text unique not null, discount_percent numeric default 0, active boolean default true, used_count integer default 0, max_uses integer, expires_at timestamptz, created_at timestamptz default now());
create table if not exists orders (id uuid primary key default gen_random_uuid(), user_id uuid references users(id), name text, phone text, address text, total numeric(12,2) not null default 0, status text default 'placed', coupon_code text, discount_amount numeric default 0, delivery_type text default 'delivery', shipping_charge numeric default 0, is_preorder boolean default false, preferred_delivery_date date, advance_amount numeric default 0, payment_screenshot_url text, is_custom_order boolean default false, custom_request_id uuid, custom_notes text, created_at timestamptz default now());
create table if not exists order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id), product_id uuid references products(id), title text not null, price numeric(12,2) not null, quantity integer not null check(quantity>0), image_url text, is_custom boolean default false);
create table if not exists tracking (id bigint generated by default as identity primary key, order_id uuid not null references orders(id), status text, note text, created_at timestamptz default now());
create table if not exists notifications (id bigint generated by default as identity primary key, user_id uuid references users(id), message text, link text, read boolean default false, created_at timestamptz default now());
create table if not exists reviews (id bigint generated by default as identity primary key, product_id uuid references products(id), user_id uuid references users(id), rating integer check(rating between 1 and 5), comment text, created_at timestamptz default now(), unique(product_id,user_id));
create table if not exists wishlists (id bigint generated by default as identity primary key, user_id uuid references users(id), product_id uuid references products(id), created_at timestamptz default now(), unique(user_id,product_id));
create table if not exists settings (key text primary key, value text);
create table if not exists custom_requests (id uuid primary key default gen_random_uuid(), user_id uuid references users(id), name text, email text, phone text, description text, budget text, craft_type text, occasion text, size_preference text, colour_preference text, reference_image_url text, tracking_token text unique, preferred_delivery_date date, status text default 'pending', quoted_price numeric, admin_note text, customer_response text, converted_order_id uuid references orders(id), linked_product_id uuid references products(id), created_at timestamptz default now());
create table if not exists raw_materials (id bigint generated by default as identity primary key, name text not null, category text, unit text default 'pcs', current_stock numeric not null default 0 check(current_stock>=0), reorder_level numeric default 0, cost_per_unit numeric default 0, supplier text, notes text, icon text, created_at timestamptz default now());
create table if not exists components (id bigint generated by default as identity primary key, name text not null, description text, unit text default 'pcs', current_stock numeric not null default 0 check(current_stock>=0), reorder_level numeric default 0, icon text, created_at timestamptz default now());
create table if not exists component_bom (id bigint generated by default as identity primary key, component_id bigint references components(id), material_id bigint references raw_materials(id), quantity_used numeric not null check(quantity_used>0));
create table if not exists product_bom (id bigint generated by default as identity primary key, product_id uuid references products(id), item_type text check(item_type in ('material','component')), material_id bigint references raw_materials(id), component_id bigint references components(id), quantity_used numeric not null check(quantity_used>0));
create table if not exists product_materials (id bigint generated by default as identity primary key, product_id uuid references products(id), material_id bigint references raw_materials(id), quantity_used numeric not null);
create table if not exists product_costs (id bigint generated by default as identity primary key, product_id uuid unique references products(id), labour_cost numeric default 0, overhead_cost numeric default 0, margin_percent numeric default 30, updated_at timestamptz default now());
create table if not exists expenditures (id bigint generated by default as identity primary key, material_id bigint references raw_materials(id), quantity numeric, cost_per_unit numeric, total_cost numeric, supplier text, notes text, purchased_at timestamptz default now());
create table if not exists manufacture_log (id bigint generated by default as identity primary key, component_id bigint references components(id), quantity_made numeric, wastage_percent numeric default 0, waste_cost numeric default 0, notes text, manufactured_at timestamptz default now());
create table if not exists order_requirements (id bigint generated by default as identity primary key, order_id uuid references orders(id), item_type text, material_id bigint references raw_materials(id), component_id bigint references components(id), quantity_needed numeric);
create table if not exists auth_tokens (id uuid primary key default gen_random_uuid(), user_id uuid references users(id), token text unique not null, type text not null, expires_at timestamptz not null, used boolean default false, created_at timestamptz default now());
create table if not exists gift_cards (id bigint generated by default as identity primary key, code text unique not null, amount numeric not null, balance numeric not null check(balance>=0), active boolean default true, recipient_email text, recipient_name text, message text, expires_at timestamptz, created_at timestamptz default now());
create table if not exists returns (id uuid primary key default gen_random_uuid(), order_id uuid references orders(id), user_id uuid references users(id), reason text, status text default 'pending', admin_note text, created_at timestamptz default now());
create table if not exists faqs (id bigint generated by default as identity primary key, question text, answer text, sort_order integer default 0, active boolean default true, created_at timestamptz default now());
create table if not exists broadcasts (id bigint generated by default as identity primary key, subject text, body text, sent_to integer, created_at timestamptz default now());
create table if not exists back_in_stock_alerts (id bigint generated by default as identity primary key, product_id uuid references products(id), user_id uuid references users(id), email text, notified boolean default false, created_at timestamptz default now());
create table if not exists email_templates (key text primary key, subject text, body_html text, updated_at timestamptz default now());
create table if not exists email_log (id bigint generated by default as identity primary key, to_email text, subject text, body text, sent_by uuid references users(id), related_type text, related_id text, sent_at timestamptz default now());
commit;
